const html = "<!doctype html>\n<html lang=\"ko\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Quant Career Pipeline Dashboard</title>\n  <style>\n    :root {\n      --bg: #f4f6f8;\n      --panel: #ffffff;\n      --ink: #17202a;\n      --muted: #667085;\n      --line: #d7dde6;\n      --head: #202833;\n      --green: #14745a;\n      --blue: #215f9a;\n      --amber: #9a640d;\n      --red: #a33b34;\n      --violet: #6654a8;\n      --soft-green: #e8f4ef;\n      --soft-blue: #eaf2fb;\n      --soft-amber: #fff4df;\n      --soft-red: #faeeee;\n      --soft-violet: #f0eef9;\n      --soft-gray: #f8fafc;\n    }\n\n    * { box-sizing: border-box; }\n\n    body {\n      margin: 0;\n      background: var(--bg);\n      color: var(--ink);\n      font-family: -apple-system, BlinkMacSystemFont, \"Apple SD Gothic Neo\", \"Noto Sans KR\", \"Segoe UI\", sans-serif;\n      line-height: 1.45;\n    }\n\n    .topbar {\n      background: var(--head);\n      color: #fff;\n      border-bottom: 1px solid #111820;\n    }\n\n    .topbar-inner {\n      width: min(1480px, calc(100% - 32px));\n      margin: 0 auto;\n      padding: 18px 0;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 18px;\n    }\n\n    h1 {\n      margin: 0;\n      font-size: 24px;\n      letter-spacing: 0;\n      line-height: 1.18;\n    }\n\n    .subtitle {\n      margin: 4px 0 0;\n      color: #c9d3df;\n      font-size: 13px;\n    }\n\n    .updated {\n      text-align: right;\n      color: #c9d3df;\n      font-size: 12px;\n      min-width: 220px;\n    }\n\n    main {\n      width: min(1480px, calc(100% - 32px));\n      margin: 0 auto;\n      padding: 18px 0 44px;\n    }\n\n    .tabs, .filters {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 8px;\n      align-items: center;\n    }\n\n    .tabs {\n      margin-bottom: 14px;\n      overflow-x: auto;\n      flex-wrap: nowrap;\n      padding-bottom: 2px;\n    }\n\n    button, input, select {\n      font: inherit;\n    }\n\n    button {\n      flex: 0 0 auto;\n      min-height: 34px;\n      border: 1px solid var(--line);\n      background: var(--panel);\n      color: #344054;\n      border-radius: 7px;\n      padding: 7px 11px;\n      cursor: pointer;\n      font-weight: 700;\n    }\n\n    button.active {\n      background: var(--head);\n      color: #fff;\n      border-color: var(--head);\n    }\n\n    input, select {\n      min-height: 36px;\n      border: 1px solid var(--line);\n      background: #fff;\n      color: var(--ink);\n      border-radius: 7px;\n      padding: 7px 10px;\n    }\n\n    input {\n      width: min(420px, 100%);\n    }\n\n    section {\n      background: var(--panel);\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      padding: 18px;\n      margin: 14px 0;\n    }\n\n    .section-title {\n      display: flex;\n      align-items: baseline;\n      justify-content: space-between;\n      gap: 12px;\n      flex-wrap: wrap;\n      margin-bottom: 12px;\n    }\n\n    h2 {\n      margin: 0;\n      font-size: 18px;\n      letter-spacing: 0;\n    }\n\n    .note {\n      color: var(--muted);\n      font-size: 13px;\n      overflow-wrap: anywhere;\n    }\n\n    .metrics {\n      display: grid;\n      grid-template-columns: repeat(6, minmax(0, 1fr));\n      gap: 10px;\n    }\n\n    .metric {\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      padding: 12px;\n      background: var(--soft-gray);\n      min-height: 86px;\n    }\n\n    .metric b {\n      display: block;\n      font-size: 25px;\n      line-height: 1;\n      margin-bottom: 7px;\n    }\n\n    .metric span {\n      color: var(--muted);\n      font-size: 12px;\n    }\n\n    .layout {\n      display: grid;\n      grid-template-columns: 1.05fr 0.95fr;\n      gap: 14px;\n      align-items: start;\n    }\n\n    table {\n      width: 100%;\n      border-collapse: collapse;\n      font-size: 13px;\n    }\n\n    th, td {\n      border-bottom: 1px solid var(--line);\n      padding: 10px 8px;\n      text-align: left;\n      vertical-align: top;\n    }\n\n    th {\n      background: #f1f4f8;\n      color: #344054;\n      font-size: 12px;\n      position: sticky;\n      top: 0;\n      z-index: 1;\n    }\n\n    tr:hover td {\n      background: #fbfdff;\n    }\n\n    a {\n      color: var(--blue);\n      text-decoration: none;\n    }\n\n    a:hover {\n      text-decoration: underline;\n    }\n\n    .table-wrap {\n      max-height: 620px;\n      overflow: auto;\n      border: 1px solid var(--line);\n      border-radius: 8px;\n    }\n\n    .pill {\n      display: inline-flex;\n      align-items: center;\n      min-height: 22px;\n      padding: 2px 8px;\n      border-radius: 999px;\n      font-size: 12px;\n      font-weight: 800;\n      white-space: nowrap;\n    }\n\n    .apply { color: var(--green); background: var(--soft-green); }\n    .verify { color: var(--amber); background: var(--soft-amber); }\n    .watch { color: var(--blue); background: var(--soft-blue); }\n    .hold { color: var(--red); background: var(--soft-red); }\n    .researched { color: var(--violet); background: var(--soft-violet); }\n    .unknown { color: #475467; background: #eef2f7; }\n\n    .score {\n      font-weight: 900;\n      white-space: nowrap;\n    }\n\n    .score.elite, .score.strong { color: var(--green); }\n    .score.watch { color: var(--amber); }\n    .score.low { color: var(--red); }\n\n    .kanban {\n      display: grid;\n      grid-template-columns: repeat(5, minmax(0, 1fr));\n      gap: 10px;\n    }\n\n    .lane {\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      background: #fbfcfe;\n      min-height: 260px;\n      overflow: hidden;\n    }\n\n    .lane h3 {\n      margin: 0;\n      padding: 10px 12px;\n      font-size: 13px;\n      border-bottom: 1px solid var(--line);\n      background: #f1f4f8;\n      letter-spacing: 0;\n    }\n\n    .job-card {\n      padding: 11px 12px;\n      border-bottom: 1px solid var(--line);\n      background: #fff;\n    }\n\n    .job-card:last-child {\n      border-bottom: 0;\n    }\n\n    .job-card b {\n      display: block;\n      margin-bottom: 5px;\n      font-size: 13px;\n    }\n\n    .job-card p {\n      margin: 5px 0 0;\n      color: var(--muted);\n      font-size: 12px;\n    }\n\n    .history-grid {\n      display: grid;\n      grid-template-columns: repeat(4, minmax(0, 1fr));\n      gap: 10px;\n    }\n\n    .history-item {\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      padding: 12px;\n      background: #fbfcfe;\n      min-height: 108px;\n    }\n\n    .history-item b {\n      display: block;\n      margin-bottom: 8px;\n    }\n\n    .brief-list {\n      display: grid;\n      gap: 8px;\n      margin: 0;\n      padding: 0;\n      list-style: none;\n    }\n\n    .brief-list li {\n      border-left: 4px solid var(--blue);\n      background: #f8fafc;\n      padding: 9px 11px;\n      color: #344054;\n      font-size: 13px;\n    }\n\n    .hidden {\n      display: none;\n    }\n\n    @media (max-width: 1100px) {\n      .metrics { grid-template-columns: repeat(3, minmax(0, 1fr)); }\n      .layout, .kanban { grid-template-columns: 1fr; }\n      .history-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n      .updated { text-align: left; min-width: 0; }\n      .topbar-inner { flex-direction: column; align-items: flex-start; }\n    }\n\n    @media (max-width: 720px) {\n      .metrics, .history-grid { grid-template-columns: 1fr; }\n      main, .topbar-inner { width: min(100% - 20px, 1480px); }\n      section { padding: 14px; }\n      .table-wrap { max-height: none; overflow-x: auto; }\n      table { min-width: 860px; }\n    }\n  </style>\n</head>\n<body>\n  <header class=\"topbar\">\n    <div class=\"topbar-inner\">\n      <div>\n        <h1>Quant Career Pipeline</h1>\n        <p class=\"subtitle\">Singapore primary, SG-compatible remote, and Texas/Dallas expansion. Built from existing scan history, target tracker, and JD cache.</p>\n      </div>\n      <div class=\"updated\" id=\"updated\">Loading...</div>\n    </div>\n  </header>\n\n  <main>\n    <nav class=\"tabs\" aria-label=\"Dashboard views\">\n      <button class=\"active\" data-tab=\"overview\">Overview</button>\n      <button data-tab=\"board\">Candidate Board</button>\n      <button data-tab=\"history\">History</button>\n      <button data-tab=\"jd\">JD Cache</button>\n    </nav>\n\n    <section id=\"overview\">\n      <div class=\"section-title\">\n        <h2>Pipeline Metrics</h2>\n        <span class=\"note\" id=\"source-note\"></span>\n      </div>\n      <div class=\"metrics\" id=\"metrics\"></div>\n    </section>\n\n    <div class=\"layout tab-pane\" data-pane=\"overview\">\n      <section>\n        <div class=\"section-title\">\n          <h2>Top Targets</h2>\n          <span class=\"note\">score >= 4.0</span>\n        </div>\n        <div class=\"table-wrap\">\n          <table>\n            <thead>\n              <tr>\n                <th>Company</th>\n                <th>Score</th>\n                <th>Action</th>\n                <th>Geo</th>\n                <th>Last Seen</th>\n                <th>Notes</th>\n              </tr>\n            </thead>\n            <tbody id=\"top-table\"></tbody>\n          </table>\n        </div>\n      </section>\n\n      <section>\n        <div class=\"section-title\">\n          <h2>Latest Scope Brief</h2>\n          <span class=\"note\">from 2026-07-21 expansion brief</span>\n        </div>\n        <ul class=\"brief-list\" id=\"brief-list\"></ul>\n      </section>\n    </div>\n\n    <section class=\"tab-pane\" data-pane=\"overview\">\n      <div class=\"section-title\">\n        <h2>Action Board</h2>\n        <span class=\"note\">derived from score, status, and tracker notes</span>\n      </div>\n      <div class=\"kanban\" id=\"kanban\"></div>\n    </section>\n\n    <section class=\"tab-pane hidden\" data-pane=\"board\">\n      <div class=\"section-title\">\n        <h2>Candidate Board</h2>\n        <span class=\"note\" id=\"board-count\"></span>\n      </div>\n      <div class=\"filters\">\n        <input id=\"search\" placeholder=\"Search company, status, notes\">\n        <select id=\"action-filter\">\n          <option value=\"all\">All actions</option>\n          <option value=\"apply\">Apply</option>\n          <option value=\"verify\">Verify</option>\n          <option value=\"watch\">Watch</option>\n          <option value=\"researched\">Researched</option>\n          <option value=\"hold\">Hold</option>\n        </select>\n        <select id=\"geo-filter\">\n          <option value=\"all\">All geos</option>\n          <option value=\"Singapore\">Singapore</option>\n          <option value=\"Texas/Dallas\">Texas/Dallas</option>\n          <option value=\"Remote\">Remote</option>\n          <option value=\"APAC\">APAC</option>\n          <option value=\"Location blocked\">Location blocked</option>\n        </select>\n      </div>\n      <div class=\"table-wrap\" style=\"margin-top: 12px;\">\n        <table>\n          <thead>\n            <tr>\n              <th>Company</th>\n              <th>Status</th>\n              <th>Score</th>\n              <th>Action</th>\n              <th>Geo</th>\n              <th>Last Seen</th>\n              <th>Notes</th>\n            </tr>\n          </thead>\n          <tbody id=\"company-table\"></tbody>\n        </table>\n      </div>\n    </section>\n\n    <section class=\"tab-pane hidden\" data-pane=\"history\">\n      <div class=\"section-title\">\n        <h2>Scan History</h2>\n        <span class=\"note\">latest parsed markdown sections</span>\n      </div>\n      <div class=\"history-grid\" id=\"history-grid\"></div>\n    </section>\n\n    <section class=\"tab-pane hidden\" data-pane=\"jd\">\n      <div class=\"section-title\">\n        <h2>JD Cache</h2>\n        <span class=\"note\" id=\"jd-count\"></span>\n      </div>\n      <div class=\"filters\">\n        <input id=\"jd-search\" placeholder=\"Search cached JD title, file, excerpt\">\n      </div>\n      <div class=\"table-wrap\" style=\"margin-top: 12px;\">\n        <table>\n          <thead>\n            <tr>\n              <th>Cached JD</th>\n              <th>Date</th>\n              <th>Source</th>\n              <th>Excerpt</th>\n            </tr>\n          </thead>\n          <tbody id=\"jd-table\"></tbody>\n        </table>\n      </div>\n    </section>\n  </main>\n\n  <script type=\"module\">\n    const actionLabels = {\n      apply: \"Apply\",\n      verify: \"Verify\",\n      watch: \"Watch\",\n      researched: \"Researched\",\n      hold: \"Hold\",\n      unknown: \"Unknown\"\n    };\n\n    const actionOrder = [\"apply\", \"verify\", \"watch\", \"researched\", \"hold\"];\n    let state = null;\n\n    function esc(value) {\n      return String(value ?? \"\").replace(/[&<>\"']/g, (char) => ({\n        \"&\": \"&amp;\",\n        \"<\": \"&lt;\",\n        \">\": \"&gt;\",\n        \"\\\"\": \"&quot;\",\n        \"'\": \"&#039;\"\n      })[char]);\n    }\n\n    function actionPill(action) {\n      const normalized = actionLabels[action] ? action : \"unknown\";\n      return `<span class=\"pill ${normalized}\">${actionLabels[normalized]}</span>`;\n    }\n\n    function scoreCell(item) {\n      const score = item.score === null ? \"n/a\" : item.score.toFixed(1);\n      return `<span class=\"score ${esc(item.scoreBucket)}\">${score}</span>`;\n    }\n\n    function shortNotes(notes, limit = 160) {\n      if (!notes) return \"\";\n      return notes.length > limit ? `${notes.slice(0, limit - 1)}...` : notes;\n    }\n\n    function renderMetrics(data) {\n      const metrics = [\n        [\"Tracked\", data.metrics.trackedCompanies, \"companies in target tracker\"],\n        [\"Top\", data.metrics.topTargets, \"companies scoring 4.0+\"],\n        [\"JD\", data.metrics.jdCacheFiles, \"cached job descriptions\"],\n        [\"Apply\", data.metrics.applyFirst, \"immediate apply bucket\"],\n        [\"Verify\", data.metrics.verify, \"needs JD/location check\"],\n        [\"Scans\", data.metrics.scansParsed, \"recent parsed scan sections\"]\n      ];\n\n      document.getElementById(\"metrics\").innerHTML = metrics.map(([label, value, note]) => `\n        <div class=\"metric\">\n          <b>${esc(value)}</b>\n          <span>${esc(label)} · ${esc(note)}</span>\n        </div>\n      `).join(\"\");\n    }\n\n    function renderTop(data) {\n      document.getElementById(\"top-table\").innerHTML = data.top.map((item) => `\n        <tr>\n          <td><b>${esc(item.company)}</b><br><span class=\"note\">${esc(item.status)}</span></td>\n          <td>${scoreCell(item)}<br><span class=\"note\">${esc(item.fitScoreRaw)}</span></td>\n          <td>${actionPill(item.action)}</td>\n          <td>${esc(item.geo)}</td>\n          <td>${esc(item.lastSeen)}</td>\n          <td>${esc(shortNotes(item.notes, 210))}</td>\n        </tr>\n      `).join(\"\");\n    }\n\n    function renderBrief(data) {\n      document.getElementById(\"brief-list\").innerHTML = data.latestBrief.scope.map((line) => `\n        <li>${esc(line)}</li>\n      `).join(\"\");\n    }\n\n    function renderKanban(data) {\n      const lanes = actionOrder.map((action) => {\n        const items = data.companies\n          .filter((item) => item.action === action)\n          .sort((a, b) => (b.score ?? -1) - (a.score ?? -1))\n          .slice(0, 8);\n        return `\n          <div class=\"lane\">\n            <h3>${actionLabels[action]} · ${data.companies.filter((item) => item.action === action).length}</h3>\n            ${items.map((item) => `\n              <div class=\"job-card\">\n                <b>${esc(item.company)} · ${item.score === null ? \"n/a\" : item.score.toFixed(1)}</b>\n                <span class=\"note\">${esc(item.geo)} · ${esc(item.lastSeen)}</span>\n                <p>${esc(shortNotes(item.notes, 112))}</p>\n              </div>\n            `).join(\"\")}\n          </div>\n        `;\n      });\n      document.getElementById(\"kanban\").innerHTML = lanes.join(\"\");\n    }\n\n    function filteredCompanies() {\n      const q = document.getElementById(\"search\").value.trim().toLowerCase();\n      const action = document.getElementById(\"action-filter\").value;\n      const geo = document.getElementById(\"geo-filter\").value;\n\n      return state.companies.filter((item) => {\n        const haystack = `${item.company} ${item.status} ${item.notes} ${item.geo}`.toLowerCase();\n        return (!q || haystack.includes(q))\n          && (action === \"all\" || item.action === action)\n          && (geo === \"all\" || item.geo === geo);\n      });\n    }\n\n    function renderCompanyTable() {\n      const rows = filteredCompanies();\n      document.getElementById(\"board-count\").textContent = `${rows.length} visible / ${state.companies.length} total`;\n      document.getElementById(\"company-table\").innerHTML = rows.map((item) => `\n        <tr>\n          <td><b>${esc(item.company)}</b></td>\n          <td>${esc(item.status)}</td>\n          <td>${scoreCell(item)}<br><span class=\"note\">${esc(item.fitScoreRaw)}</span></td>\n          <td>${actionPill(item.action)}</td>\n          <td>${esc(item.geo)}</td>\n          <td>${esc(item.lastSeen)}</td>\n          <td>${esc(item.notes)}</td>\n        </tr>\n      `).join(\"\");\n    }\n\n    function renderHistory(data) {\n      document.getElementById(\"history-grid\").innerHTML = data.history.scans.map((scan) => `\n        <div class=\"history-item\">\n          <b>${esc(scan.date)}</b>\n          <div class=\"note\">${esc(scan.title)}</div>\n          <p>mentions: ${esc(scan.candidateMentions)} · companies: ${esc(scan.uniqueCompanies)}</p>\n          <p>scores: ${esc(scan.scoreCount)} · max: ${esc(scan.maxScore ?? \"n/a\")}</p>\n        </div>\n      `).join(\"\");\n    }\n\n    function filteredJds() {\n      const q = document.getElementById(\"jd-search\").value.trim().toLowerCase();\n      return state.jdCache.filter((item) => {\n        const haystack = `${item.title} ${item.file} ${item.excerpt}`.toLowerCase();\n        return !q || haystack.includes(q);\n      });\n    }\n\n    function renderJdTable() {\n      const rows = filteredJds();\n      document.getElementById(\"jd-count\").textContent = `${rows.length} visible / ${state.jdCache.length} cached files`;\n      document.getElementById(\"jd-table\").innerHTML = rows.map((item) => `\n        <tr>\n          <td><b>${esc(item.title)}</b><br><span class=\"note\">${esc(item.file)}</span></td>\n          <td>${esc(item.date ?? \"n/a\")}</td>\n          <td>${item.url ? `<a href=\"${esc(item.url)}\" target=\"_blank\" rel=\"noreferrer\">source</a>` : `<span class=\"note\">${esc(item.path)}</span>`}</td>\n          <td>${esc(item.excerpt)}</td>\n        </tr>\n      `).join(\"\");\n    }\n\n    function activateTab(tab) {\n      document.querySelectorAll(\".tabs button\").forEach((button) => {\n        button.classList.toggle(\"active\", button.dataset.tab === tab);\n      });\n      document.querySelectorAll(\".tab-pane\").forEach((pane) => {\n        pane.classList.toggle(\"hidden\", pane.dataset.pane !== tab);\n      });\n    }\n\n    async function boot() {\n      const response = await fetch(\"./data/dashboard.json\", { cache: \"no-store\" });\n      state = await response.json();\n\n      document.getElementById(\"updated\").textContent = `Generated ${new Date(state.generatedAt).toLocaleString(\"ko-KR\", { timeZone: \"Asia/Seoul\" })} KST`;\n      document.getElementById(\"source-note\").textContent = `Sources: ${Object.values(state.sourceFiles).join(\" · \")}`;\n\n      renderMetrics(state);\n      renderTop(state);\n      renderBrief(state);\n      renderKanban(state);\n      renderCompanyTable();\n      renderHistory(state);\n      renderJdTable();\n\n      document.querySelectorAll(\".tabs button\").forEach((button) => {\n        button.addEventListener(\"click\", () => activateTab(button.dataset.tab));\n      });\n      [\"search\", \"action-filter\", \"geo-filter\"].forEach((id) => {\n        document.getElementById(id).addEventListener(\"input\", renderCompanyTable);\n      });\n      document.getElementById(\"jd-search\").addEventListener(\"input\", renderJdTable);\n    }\n\n    boot().catch((error) => {\n      document.getElementById(\"updated\").textContent = \"Failed to load dashboard data\";\n      console.error(error);\n    });\n  </script>\n</body>\n</html>\n";
